Mechanism.Pattern:
// Selection pseudocode:
var calculator = ResolveCalculator(method.CalculatorType);
var context = ShipmentContext.Create(itemTotal, weight, contents);
var cost = calculator.Compute(context);

Scenario.Pattern:
// Create shipment
var result = ShipmentExtensions.Create(orderId, stockLocationId);
if (result.IsFailure) { /* handle error */ }
var shipment = result.Value;

// Select a shipping rate
shipment.SelectShippingRate(rateId);

// Transition through lifecycle
shipment.Ready();
shipment.Ship(trackingNumber);

var calculator = new FlatRateShippingCalculator
{
    Amount = 10.00m,
    MaximumItemTotal = 500.00m
};

var context = ShipmentContext.Create(
    itemTotal: 120.00m,
    weight: 3.5m,
    contents: new List<ShipmentContentItem> { ... }
);

decimal? cost = calculator.Compute(context);
// cost == 10.00 (within bounds)

Strategy.CodeExample:
[Fact]
public void FlatRate_WithinBounds_ReturnsAmount()
{
    var calc = new FlatRateShippingCalculator { Amount = 5m };
    var ctx = ShipmentContext.Create(100m, 10m, []);
    var cost = calc.Compute(ctx);
    Assert.Equal(5m, cost);
}

[Fact]
public void Ship_FromReady_ReturnsSuccess()
{
    var shipment = ...; // fixture in Ready state
    var result = shipment.Ship("TRACK123");
    Assert.True(result.IsSuccess);
    Assert.Equal(ShipmentState.Shipped, shipment.State);
}
